          {/* ÔöÇÔöÇ Section 1 : Active Harvests ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
          <View style={styles.sectionHeader}>
            <Text style={styles.sectionTitle}>Active Harvests</Text>
            <Text style={styles.sectionCount}>{ACTIVE_HARVESTS.length}</Text>
          </View>
          {ACTIVE_HARVESTS.map((harvest) => (
            <HarvestCard
              key={harvest.id}
              cropName={harvest.cropName}
              yieldPercent={harvest.yieldPercent}
              estimatedValue={harvest.estimatedValue}
              progress={harvest.progress}
              icon={harvest.icon}
            />
          ))}

          {/* ÔöÇÔöÇ Section 2 : Buyer Activity ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
