            <Text style={styles.seeAll}>See All</Text>
          </View>
          {BUYER_ACTIVITY.map((item) => (
            <NotificationCard
              key={item.id}
              icon={item.icon}
              title={item.title}
              description={item.description}
              time={item.time}
              iconColor={item.iconColor}
              unread={item.unread}
