            <AnalyticsCard
              label="Soil Moisture"
              value="42%"
              icon="water-outline"
            />
            <AnalyticsCard
              label="Solar Exposure"
              value="8.2 hrs"
              icon="sunny-outline"
            />
          </ScrollView>
        </Animated.View>

        {/* Bottom spacing for floating tab bar */}
        <View style={{ height: 100 }} />
      </ScrollView>
    </SafeAreaView>
  );
}

