} from 'react-native';

/**
 * LoginScreen
 * Auth flow entry point ÔÇö email / password login with
 * "Remember this device" and "Forgot Password?" options.
 */
export default function LoginScreen() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [remember, setRemember] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const router = useRouter();

  /* ÔöÇÔöÇ Intro fade animation ÔöÇÔöÇ */
  const fadeAnim = useRef(new Animated.Value(0)).current;
  const slideAnim = useRef(new Animated.Value(20)).current;
  const pulseAnim = useRef(new Animated.Value(1)).current;

  useEffect(() => {
    Animated.parallel([
      Animated.timing(fadeAnim, {
        toValue: 1,
        duration: 600,
        useNativeDriver: true,
      }),
      Animated.timing(slideAnim, {
        toValue: 0,
        duration: 600,
        useNativeDriver: true,
      }),
    ]).start();

    // Pulse the leaf icon
    Animated.loop(
      Animated.sequence([
        Animated.timing(pulseAnim, {
          toValue: 1.08,
          duration: 1500,
          useNativeDriver: true,
        }),
        Animated.timing(pulseAnim, {
          toValue: 1,
          duration: 1500,
          useNativeDriver: true,
        }),
      ])
    ).start();
  }, []);

  const handleLogin = () => {
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      router.replace('/(tabs)');
    }, 1500);
  };

  return (
    <SafeAreaView style={styles.safeArea}>
      <ScrollView
        contentContainerStyle={styles.container}
        keyboardShouldPersistTaps="handled"
        showsVerticalScrollIndicator={false}
      >
        <Animated.View
          style={[
            styles.content,
            {
              opacity: fadeAnim,
              transform: [{ translateY: slideAnim }],
            },
          ]}
        >
          {/* Brand header */}
          <Text style={styles.header}>THE DIGITAL AGRONOMIST</Text>

          {/* Decorative leaf icon */}
          <Animated.View
            style={[styles.iconWrap, { transform: [{ scale: pulseAnim }] }]}
          >
            <Ionicons name="leaf" size={36} color={Colors.light.tint} />
          </Animated.View>

          {/* Welcome text */}
          <Text style={styles.title}>Welcome Back</Text>
          <Text style={styles.subtitle}>
            Please enter your details to access your dashboard.
          </Text>

          {/* Email */}
          <CustomInput
            label="Email Address"
            placeholder="Enter your email"
            value={email}
            onChangeText={setEmail}
            keyboardType="email-address"
            autoCapitalize="none"
          />

          {/* Password */}
          <CustomInput
            label="Password"
            placeholder="Enter your password"
            value={password}
            onChangeText={setPassword}
            secureTextEntry
          />

          {/* Remember + Forgot row */}
          <View style={styles.optionsRow}>
            <TouchableOpacity
              style={styles.checkboxRow}
              onPress={() => setRemember(!remember)}
              activeOpacity={0.7}
            >
              <Ionicons
                name={remember ? 'checkbox' : 'square-outline'}
                size={22}
                color={Colors.light.tint}
              />
              <Text style={styles.checkboxLabel}>Remember me</Text>
            </TouchableOpacity>

            <TouchableOpacity>
              <Text style={styles.forgotText}>Forgot Password?</Text>
            </TouchableOpacity>
          </View>

          {/* Login button */}
          <CustomButton
            title="Login to Dashboard ÔåÆ"
            onPress={handleLogin}
            loading={isLoading}
            style={styles.loginButton}
          />

          {/* Create account */}
          <CustomButton
            title="Create an Account"
            onPress={() => router.push('/signup')}
            variant="secondary"
            style={styles.signupButton}
          />
        </Animated.View>
      </ScrollView>

      {/* Bottom gradient accent line */}
      <View style={styles.bottomAccent} />
    </SafeAreaView>
  );
}

