} from 'react-native';

const LANGUAGES = [
  { code: 'en', label: 'English', native: 'English' },
  { code: 'fr', label: 'French', native: 'Fran├ºais' },
  { code: 'sw', label: 'Swahili', native: 'Kiswahili' },
  { code: 'ar', label: 'Arabic', native: 'Ïº┘äÏ╣Ï▒Ï¿┘èÏ®' },
  { code: 'pt', label: 'Portuguese', native: 'Portugu├¬s' },
  { code: 'es', label: 'Spanish', native: 'Espa├▒ol' },
  { code: 'zh', label: 'Chinese', native: 'õ©¡µûç' },
];

export default function LanguageScreen() {
  const [selected, setSelected] = useState('en');

  return (
    <SafeAreaView style={styles.safeArea}>
      <ScrollView contentContainerStyle={styles.container} showsVerticalScrollIndicator={false}>
        <Text style={styles.sectionTitle}>Select Language</Text>
        <Card style={styles.card}>
          {LANGUAGES.map((lang, idx) => (
            <TouchableOpacity
              key={lang.code}
              style={[styles.row, idx < LANGUAGES.length - 1 && styles.rowBorder]}
              onPress={() => setSelected(lang.code)}
              activeOpacity={0.7}
            >
              <View style={styles.textWrap}>
                <Text style={styles.label}>{lang.label}</Text>
                <Text style={styles.native}>{lang.native}</Text>
              </View>
              <Ionicons
                name={selected === lang.code ? 'checkmark-circle' : 'ellipse-outline'}
                size={22}
                color={selected === lang.code ? Colors.light.tint : '#D1D5DB'}
              />
            </TouchableOpacity>
          ))}
        </Card>
        <Text style={styles.note}>
          Changing the language will restart the app to apply the new setting.
        </Text>
      </ScrollView>
    </SafeAreaView>
  );
}

