interface NotifToggle {
  key: string;
  label: string;
  hint: string;
  defaultValue: boolean;
}

const PUSH_TOGGLES: NotifToggle[] = [
  { key: 'orders', label: 'New Orders', hint: 'Receive alerts when buyers place orders', defaultValue: true },
  { key: 'bids', label: 'Bid Updates', hint: 'Get notified about new and changed bids', defaultValue: true },
  { key: 'messages', label: 'Messages', hint: 'Alerts for new buyer messages', defaultValue: true },
  { key: 'sync', label: 'Sync Status', hint: 'Notifications about data upload progress', defaultValue: false },
  { key: 'market', label: 'Market Watch', hint: 'Daily commodity price updates', defaultValue: true },
];

const EMAIL_TOGGLES: NotifToggle[] = [
  { key: 'weekly', label: 'Weekly Digest', hint: 'Summary of your farm activity every Monday', defaultValue: true },
  { key: 'promo', label: 'Promotions', hint: 'Special offers and new features', defaultValue: false },
  { key: 'audits', label: 'Audit Reminders', hint: 'Upcoming certification audit alerts', defaultValue: true },
];

export default function NotificationPreferencesScreen() {
  const [push, setPush] = useState<Record<string, boolean>>(
    Object.fromEntries(PUSH_TOGGLES.map((t) => [t.key, t.defaultValue]))
  );
  const [emailPrefs, setEmailPrefs] = useState<Record<string, boolean>>(
    Object.fromEntries(EMAIL_TOGGLES.map((t) => [t.key, t.defaultValue]))
  );

  const togglePush = (key: string) => setPush((prev) => ({ ...prev, [key]: !prev[key] }));
  const toggleEmail = (key: string) => setEmailPrefs((prev) => ({ ...prev, [key]: !prev[key] }));

  return (
    <SafeAreaView style={styles.safeArea}>
      <ScrollView contentContainerStyle={styles.container} showsVerticalScrollIndicator={false}>
        <Text style={styles.sectionTitle}>Push Notifications</Text>
        <Card style={styles.card}>
          {PUSH_TOGGLES.map((item, idx) => (
            <View
              key={item.key}
              style={[styles.row, idx < PUSH_TOGGLES.length - 1 && styles.rowBorder]}
            >
              <View style={styles.textWrap}>
                <Text style={styles.label}>{item.label}</Text>
                <Text style={styles.hint}>{item.hint}</Text>
              </View>
              <Switch
                trackColor={{ false: '#D1D5DB', true: '#A5D6A7' }}
                thumbColor={push[item.key] ? Colors.light.tint : '#f4f3f4'}
                value={push[item.key]}
                onValueChange={() => togglePush(item.key)}
              />
            </View>
          ))}
        </Card>

        <Text style={styles.sectionTitle}>Email Notifications</Text>
        <Card style={styles.card}>
          {EMAIL_TOGGLES.map((item, idx) => (
            <View
              key={item.key}
              style={[styles.row, idx < EMAIL_TOGGLES.length - 1 && styles.rowBorder]}
            >
              <View style={styles.textWrap}>
                <Text style={styles.label}>{item.label}</Text>
                <Text style={styles.hint}>{item.hint}</Text>
              </View>
              <Switch
                trackColor={{ false: '#D1D5DB', true: '#A5D6A7' }}
                thumbColor={emailPrefs[item.key] ? Colors.light.tint : '#f4f3f4'}
                value={emailPrefs[item.key]}
                onValueChange={() => toggleEmail(item.key)}
              />
            </View>
          ))}
        </Card>
      </ScrollView>
    </SafeAreaView>
  );
}

