import { Colors, Radius } from '@/constants/theme';
import React, { useEffect } from 'react';
import { StyleProp, StyleSheet, View, ViewStyle } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withTiming,
} from 'react-native-reanimated';

interface ProgressBarProps {
  progress: number;
  color?: string;
  trackColor?: string;
  style?: StyleProp<ViewStyle>;
  /** Whether to animate the fill on mount */
  animated?: boolean;
}

export function ProgressBar({
  progress,
  color = Colors.light.tint,
  trackColor,
  style,
  animated = true,
}: ProgressBarProps) {
  const clampedProgress = Math.max(0, Math.min(1, progress));
  const width = useSharedValue(animated ? 0 : clampedProgress);

  useEffect(() => {
    if (animated) {
      width.value = withTiming(clampedProgress, { duration: 800 });
    } else {
      width.value = clampedProgress;
    }
  }, [clampedProgress, animated]);

  const animatedStyle = useAnimatedStyle(() => ({
    width: `${width.value * 100}%`,
  }));

  return (
    <View
      style={[
        styles.container,
        trackColor ? { backgroundColor: trackColor } : null,
        style,
      ]}
    >
      <Animated.View
        style={[
          styles.bar,
          { backgroundColor: color },
          animatedStyle,
        ]}
      />
    </View>
  );
}

