import React from 'react';
import { StyleSheet, Text, View, ViewStyle } from 'react-native';

interface StepProgressBarProps {
  currentStep: number;
  totalSteps: number;
  style?: ViewStyle;
}

/**
 * StepProgressBar
 * Connected circles with lines ÔÇö active steps are filled,
 * upcoming steps are outlined.
 */
export function StepProgressBar({ currentStep, totalSteps, style }: StepProgressBarProps) {
  return (
    <View style={[styles.wrapper, style]}>
      <Text style={styles.label}>
        Step {currentStep} of {totalSteps}
      </Text>
      <View style={styles.row}>
        {Array.from({ length: totalSteps }).map((_, i) => {
          const isCompleted = i < currentStep;
          const isCurrent = i === currentStep - 1;

          return (
            <React.Fragment key={i}>
              {/* Connector line (before each dot except the first) */}
              {i > 0 && (
                <View
                  style={[
                    styles.connector,
                    i < currentStep ? styles.connectorActive : styles.connectorInactive,
                  ]}
                />
              )}

              {/* Step dot */}
              <View
                style={[
                  styles.dot,
                  isCompleted ? styles.dotActive : styles.dotInactive,
                  isCurrent && styles.dotCurrent,
                ]}
              >
                <Text
                  style={[
                    styles.dotText,
                    isCompleted ? styles.dotTextActive : styles.dotTextInactive,
                  ]}
                >
                  {i + 1}
                </Text>
              </View>
            </React.Fragment>
          );
        })}
      </View>
    </View>
  );
}

